import sys;sys.path.insert(0,'..')
from gcommon import *
SRC=srcs([GD('git-rebase'),GD('gitworkflows','Git – gitworkflows'),GD('git-push','Git – git-push (--force-with-lease)'),GD('git-pull','Git – git-pull (--rebase)'),('https://docs.gitlab.com/user/project/merge_requests/','GitLab Docs – Merge requests')])
def dia(vi):
    t=('Rebase dời các commit của nhánh sang đỉnh mới của main' if vi else 'Rebase moves the branch\'s commits onto the new tip of main','Sơ đồ do Vinc Academy biên soạn.' if vi else 'Diagram by Vinc Academy.','dg-%s-g08'%('vi' if vi else 'en'))
    b='<text class="dg-title" x="10" y="45">%s</text><text class="dg-title" x="10" y="130">%s</text>\n'%('Trước' if vi else 'Before','Sau' if vi else 'After')
    def c(x,y,l,ac=False): return '<circle class="%s" cx="%d" cy="%d" r="16" /><text class="dg-title" text-anchor="middle" x="%d" y="%d">%s</text>\n'%('dg-accent' if ac else 'dg-box',x,y,x,y+5,l)
    b+='<path class="dg-arrow" d="M130 40 H270" /><path class="dg-arrow" d="M200 40 L270 85 H340" />\n'
    for x,l in [(130,'C1'),(200,'C2'),(270,'C3')]: b+=c(x,40,l)
    for x,l in [(270,'F1'),(340,'F2')]: b+=c(x,85,l,True)
    b+='<text class="dg-text" x="300" y="44">main</text><text class="dg-text" x="372" y="90">feature</text>\n'
    b+='<path class="dg-arrow" d="M130 130 H410" />\n'
    for x,l in [(130,'C1'),(200,'C2'),(270,'C3')]: b+=c(x,130,l)
    for x,l in [(340,"F1'"),(410,"F2'")]: b+=c(x,130,l,True)
    b+='<text class="dg-text" x="440" y="135">feature (%s)</text>\n'%('rebase' if vi else 'rebased')
    b+='<text class="dg-text" x="10" y="165">%s</text>\n'%('F1\' và F2\' có nội dung như F1, F2 nhưng là commit mới (mã băm khác).' if vi else 'F1\' and F2\' carry the same changes as F1 and F2 but are new commits (different hashes).')
    return fig('640 180',t[0],b,t[1],t[2])
def build(vi):
    t=lambda a,b:a if vi else b
    sb=SB('a08');base(sb);remote_setup(sb)
    sb.q('git remote add origin git@gitlab.example.com:vinc/vinc_course.git;git push -q -u origin main 2>&1')
    T1=sb.P('git switch -c feature/course-price',"echo \"    price = fields.Float(string='Học phí')\" >> models/course.py",'git commit -qam "[IMP] vinc_course: thêm trường học phí"','echo "# wip" >> models/course.py','git commit -qam "wip"','echo "# sửa lỗi gõ" >> models/course.py','git commit -qam "fix typo"','git push -q -u origin feature/course-price','git switch main','echo "# vinc_course" > README.md','git add README.md','git commit -qm "[ADD] vinc_course: README"','git push -q','git switch feature/course-price','git log --oneline --graph --all')
    T2=sb.P('git rebase main','git log --oneline --graph')
    T3=sb.P('git push','git push --force-with-lease')
    T4=sb.P('SEQ 2,3s/^pick/fixup/ :: git rebase -i main','git log --oneline --graph','git push --force-with-lease')
    T5=sb.P("echo \"    level = fields.Char(string='Cấp độ')\" >> models/course.py",'git commit -qam "[IMP] vinc_course: thêm cấp độ"','echo "# thiếu dấu" >> models/course.py','git commit -q --fixup HEAD -a','git log --oneline -n 3','SEQ s/zzz/zzz/ :: git rebase -i --autosquash main','git log --oneline -n 3')
    c=SB('a08c');base(c)
    c.q('git switch -qc feature/hours-label;sed -i "s/Số giờ/Số giờ học/" models/course.py;git commit -qam "[IMP] vinc_course: đổi nhãn số giờ học";git switch -q main;sed -i "s/Số giờ/Tổng số giờ/" models/course.py;git commit -qam "[IMP] vinc_course: đổi nhãn tổng số giờ";git switch -q feature/hours-label')
    T6=c.P('git rebase main','git status -sb','grep -n -A5 "<<<<<<<" models/course.py')
    c.w('models/course.py',COURSE0.replace("Số giờ","Tổng số giờ học"))
    T7=c.P('grep hours models/course.py','git add models/course.py','git rebase --continue','git log --oneline --graph')
    p_=SB('a08p');base(p_);remote_setup(p_)
    p_.q('git remote add origin git@gitlab.example.com:vinc/vinc_course.git;git push -q -u origin main 2>&1;cd .. && git clone -q git@gitlab.example.com:vinc/vinc_course.git vinc_course_binh && cd vinc_course_binh && git config user.name "Trần Thị Bình" && git config user.email "binh.tran@example.com" && echo "# vinc_course" > README.md && git add README.md && git commit -qm "[ADD] vinc_course: README" && git push -q')
    T8=p_.P("echo \"    price = fields.Float(string='Học phí')\" >> models/course.py",'git commit -qam "[IMP] vinc_course: thêm trường học phí"','git pull --rebase','git log --oneline --graph','git push')
    o=summ((t('Tóm tắt nhanh','In short'),t('<strong>Rebase “viết lại” các commit của nhánh để chúng nối tiếp trên đỉnh mới nhất của nhánh khác, cho lịch sử thẳng và gọn.</strong> Bài này dùng <code>git rebase main</code> để cập nhật nhánh tính năng, <code>git rebase -i</code> để gộp commit lẻ (<code>fixup</code>, <code>squash</code>, <code>reword</code>), <code>--autosquash</code> để tự gộp commit sửa nhỏ, xử lý xung đột khi rebase (hai bên <em>ours</em>/<em>theirs</em> bị đảo) và nắm <strong>quy tắc vàng</strong>: không rebase commit đã chia sẻ. Mọi lệnh chạy thật trên repo <code>vinc_course</code>.','<strong>Rebase “rewrites” a branch\'s commits so they sit on top of the latest tip of another branch, giving a straight, tidy history.</strong> This part uses <code>git rebase main</code> to update a feature branch, <code>git rebase -i</code> to combine small commits (<code>fixup</code>, <code>squash</code>, <code>reword</code>), <code>--autosquash</code> to fold small fix commits automatically, resolves conflicts during a rebase (where <em>ours</em> and <em>theirs</em> swap) and covers the <strong>golden rule</strong>: never rebase commits that are shared. Every command ran for real on the <code>vinc_course</code> repo.')))
    o+=h2('rebase-la-gi',t('Rebase là gì và khác merge ở đâu','What rebase is and how it differs from merge'))
    o+=p(t('Ở bài 3 bạn thấy <code>merge</code> ghép hai nhánh bằng một merge commit, giữ nguyên lịch sử “đã rẽ rồi nhập lại”. <code>rebase</code> làm khác: nó lấy các commit riêng của nhánh bạn, tạm cất đi, đưa nhánh về đỉnh mới của nhánh đích rồi <strong>phát lại</strong> từng commit lên trên. Kết quả là lịch sử một đường thẳng như thể bạn bắt đầu làm việc từ đỉnh mới ngay từ đầu.','In part 3 you saw that <code>merge</code> joins two branches with a merge commit, preserving the “split then join” history. <code>rebase</code> does it differently: it takes your branch\'s own commits, sets them aside, moves the branch to the new tip of the target and then <strong>replays</strong> each commit on top. The result is a single straight line of history, as if you had started from the new tip all along.'))
    o+=dia(vi)
    o+=p(t('Điều cần ghi nhớ nhất: commit phát lại <strong>không còn là commit cũ</strong>. Nội dung thay đổi giống nhau nhưng cha khác, nên mã băm mới (<code>F1\'</code>, <code>F2\'</code> trong sơ đồ). Đó là lý do rebase chỉ an toàn với commit chưa ai khác dựa vào.','The thing to remember most: a replayed commit is <strong>no longer the old commit</strong>. The changes are the same but the parent differs, so the hash is new (<code>F1\'</code> and <code>F2\'</code> in the diagram). That is why rebase is only safe on commits nobody else builds on.'))
    o+=tbl([t('','') ,'merge','rebase'],[[t('Lịch sử','History'),t('Có merge commit, thấy rõ lúc gộp','Has a merge commit; the moment of joining is visible'),t('Thẳng, không merge commit','Straight, no merge commit')],[t('Commit cũ','Old commits'),t('Giữ nguyên mã băm','Keep their hashes'),t('Được tạo lại với mã mới','Recreated with new hashes')],[t('Khi nào dùng','Use it when'),t('Gộp nhánh đã chia sẻ, giữ bằng chứng lịch sử','Joining shared branches; keeping a record'),t('Làm gọn nhánh riêng của bạn trước khi review','Tidying your own branch before review')]])
    o+=h2('cap-nhat',t('Cập nhật nhánh tính năng bằng rebase','Updating a feature branch with rebase'))
    o+=p(t('Giả sử bạn làm nhánh học phí với ba commit lộn xộn (một “wip”, một “fix typo”) và đã push để sao lưu. Trong lúc đó <code>main</code> có thêm một commit README, nên nhánh của bạn lệch phía sau. Đồ thị cho thấy hai đường rẽ:','Suppose you work on the price branch with three messy commits (one “wip”, one “fix typo”) and have pushed it as a backup. Meanwhile <code>main</code> gained a README commit, so your branch is behind. The graph shows the two lines splitting:'))
    o+=T1
    o+=p(t('Chạy <code>git rebase main</code> từ nhánh tính năng. Git phát lại từng commit lên sau commit README; đồ thị giờ là một đường thẳng và cả ba commit có mã băm mới:','Run <code>git rebase main</code> from the feature branch. Git replays each commit after the README commit; the graph is now one straight line and all three commits have new hashes:'))
    o+=T2
    o+=p(t('Một lưu ý thực tế: rebase không có xung đột về chữ vẫn có thể gây lỗi logic, vì code của bạn giờ chạy trên nền mới của đồng nghiệp. Hãy chạy lại test hoặc nâng cấp thử module (<code>-u vinc_course</code>) trước khi push.','A practical note: a rebase without textual conflicts can still introduce logic errors, because your code now runs on top of your colleagues\' new work. Re-run the tests or a trial module upgrade (<code>-u vinc_course</code>) before you push.'))
    o+=p(t('Vì commit đã đổi mã băm mà bản trên GitLab vẫn là bản cũ, <code>git push</code> thường sẽ bị từ chối. Với <strong>nhánh riêng của bạn</strong>, cách đúng là <code>--force-with-lease</code>: nó ghi đè nhánh remote nhưng từ chối nếu remote có commit bạn chưa thấy, nên không đè nhầm công việc của người khác:','Because the commits changed hash while GitLab still holds the old ones, a plain <code>git push</code> is normally rejected. For <strong>your own branch</strong> the right tool is <code>--force-with-lease</code>: it overwrites the remote branch but refuses if the remote has commits you have not seen, so it will not trample someone else\'s work:'))
    o+=T3
    o+=h2('squash',t('Gộp commit lẻ bằng rebase tương tác','Combining small commits with interactive rebase'))
    o+=p(t('Review dễ hơn khi nhánh kể một câu chuyện gọn. <code>git rebase -i main</code> mở một danh sách (trong editor) gồm các commit của nhánh, mỗi dòng bắt đầu bằng một lệnh. Bạn đổi chữ đầu dòng rồi lưu; Git thực hiện từ trên xuống:','Review is easier when the branch tells a short story. <code>git rebase -i main</code> opens a list (in your editor) of the branch\'s commits, each line starting with a command. You change the first word and save; Git then executes from top to bottom:'))
    o+=tbl([t('Lệnh','Command'),t('Tác dụng','Effect')],[['<code>pick</code>',t('Giữ commit như cũ','Keep the commit as is')],['<code>reword</code>',t('Giữ nội dung, sửa lời nhắn','Keep the content, edit the message')],['<code>edit</code>',t('Dừng lại để bạn sửa nội dung commit','Stop so you can change the commit\'s content')],['<code>squash</code>',t('Gộp vào commit trước, ghép cả hai lời nhắn','Fold into the previous commit and combine both messages')],['<code>fixup</code>',t('Gộp vào commit trước, bỏ lời nhắn của nó','Fold into the previous commit and discard its message')],['<code>drop</code>',t('Bỏ hẳn commit','Remove the commit entirely')]])
    o+=p(t('Các dòng bắt đầu bằng <code># editor:</code> dưới đây là danh sách mà Git đã mở. Ta đổi <code>pick</code> ở dòng 2 và 3 thành <code>fixup</code> để “wip” và “fix typo” hòa vào commit đầu:','The lines starting with <code># editor:</code> below are the list Git opened. We change <code>pick</code> on lines 2 and 3 to <code>fixup</code> so “wip” and “fix typo” melt into the first commit:'))
    o+=T4
    o+=p(t('Ba commit thành một, và vì đã viết lại nên cần <code>--force-with-lease</code> khi push. Nếu bạn biết trước một commit nhỏ sửa cho commit nào, hãy tạo nó bằng <code>git commit --fixup</code>; sau đó <code>rebase -i --autosquash</code> tự đặt commit sửa vào đúng chỗ và đổi nó thành <code>fixup</code> (xem dòng cuối của danh sách):','Three commits became one, and since it was rewritten you need <code>--force-with-lease</code> when pushing. If you know in advance which commit a small change fixes, create it with <code>git commit --fixup</code>; then <code>rebase -i --autosquash</code> puts the fix commit in the right place and turns it into <code>fixup</code> by itself (see the last line of the list):'))
    o+=T5
    o+=p(t('GitLab cũng có tùy chọn <em>squash</em> khi merge một merge request, nên nhiều nhóm không bắt buộc rebase tương tác. Dù vậy, biết tự làm gọn nhánh vẫn hữu ích vì bạn kiểm soát được lời nhắn của từng commit.','GitLab also offers a <em>squash</em> option when merging a merge request, so many teams do not require interactive rebase. Even so, tidying your own branch is useful because you control each commit\'s message.'))
    o+=h2('xung-dot',t('Xung đột khi rebase: bên “ours” và “theirs” bị đảo','Conflicts during a rebase: “ours” and “theirs” swap'))
    o+=p(t('Rebase phát lại từng commit nên xung đột có thể xảy ra ở từng bước. Cách xử lý giống bài 6, nhưng kết thúc bằng <code>git rebase --continue</code> thay vì <code>git commit</code>. Một điểm gây nhầm: theo tài liệu, khi rebase phía <em>ours</em> là chuỗi đã rebase tính từ nhánh đích, còn <em>theirs</em> là nhánh làm việc của bạn, tức <strong>hai bên bị đảo</strong> so với merge. Ví dụ: <code>main</code> đổi nhãn thành “Tổng số giờ”, nhánh của bạn đổi thành “Số giờ học”:','A rebase replays commits one by one so a conflict can arise at any step. The handling is as in part 6, but you finish with <code>git rebase --continue</code> instead of <code>git commit</code>. One source of confusion: according to the documentation, during a rebase <em>ours</em> is the already-rebased series starting from the target, and <em>theirs</em> is your working branch, so <strong>the sides are swapped</strong> compared with a merge. Example: <code>main</code> renamed the label to “Tổng số giờ” while your branch renamed it to “Số giờ học”:'))
    o+=T6
    o+=p(t('Phần sau <code>HEAD</code> là phiên bản của <code>main</code> (đích), phần dưới là commit của bạn đang được phát lại. Ta chọn nhãn kết hợp, rồi báo đã xử lý và cho rebase đi tiếp:','The part after <code>HEAD</code> is <code>main</code>\'s version (the target), the lower part is your commit being replayed. We pick a combined label, then mark it resolved and let the rebase go on:'))
    o+=T7
    o+=p(t('Nếu thấy rối, <code>git rebase --abort</code> trả nhánh về đúng như trước khi rebase; <code>git rebase --skip</code> bỏ qua commit đang gây xung đột.','If it gets messy, <code>git rebase --abort</code> returns the branch exactly to how it was before the rebase; <code>git rebase --skip</code> skips the commit that is causing the conflict.'))
    o+=h2('pull-rebase',t('git pull --rebase: kéo về mà không sinh merge commit','git pull --rebase: fetching without a merge commit'))
    o+=p(t('Ở bài 4, khi An có commit cục bộ còn Bình đã push, <code>git pull --no-rebase</code> tạo ra một merge commit tên “Merge branch \'main\' of …” chỉ để nối hai đường. Nếu bạn muốn lịch sử thẳng, hãy dùng <code>git pull --rebase</code>: Git fetch rồi phát lại commit cục bộ của bạn lên trên commit mới của remote. Vì commit của bạn chưa push nên đây là cách rebase an toàn nhất:','In part 4, when An had a local commit and Binh had already pushed, <code>git pull --no-rebase</code> created a merge commit named “Merge branch \'main\' of …” just to join the two lines. If you prefer a straight history use <code>git pull --rebase</code>: Git fetches and then replays your local commits on top of the remote\'s new ones. Because your commit is not pushed yet, this is the safest kind of rebase:'))
    o+=T8
    o+=p(t('Không có merge commit nào, và <code>git push</code> sau đó chạy suôn sẻ vì lịch sử của bạn giờ là hậu duệ trực tiếp của remote. Đây cũng là cấu hình mà nhóm chọn khi đặt <code>pull.rebase true</code>.','No merge commit appears, and the <code>git push</code> afterwards goes through cleanly because your history now continues straight from the remote\'s. This is also what a team chooses when it sets <code>pull.rebase true</code>.'))
    o+=h2('quy-tac-vang',t('Quy tắc vàng: đừng rebase thứ đã chia sẻ','The golden rule: never rebase what is shared'))
    o+=p(t('Tài liệu Git nói thẳng: rebase một nhánh mà người khác đã dựa vào là ý tồi, vì mọi người ở hạ nguồn buộc phải tự sửa lịch sử của họ. Quy tắc thực tế cho nhóm:','The Git manual is blunt: rewriting commits your colleagues already build on is risky, because everyone downstream ends up repairing their history by hand. Practical rules for a team:'))
    o+=ul([t('<strong>Rebase thoải mái</strong> nhánh tính năng riêng của bạn, trước khi hoặc trong lúc mở merge request.','<strong>Rebase freely</strong> your own feature branch, before or during a merge request.'),t('<strong>Không rebase</strong> <code>main</code>, nhánh phát hành hay bất kỳ nhánh nào có người khác đang làm trên đó.','<strong>Never rebase</strong> <code>main</code>, release branches or any branch someone else is working on.'),t('Đã rebase nhánh riêng thì push bằng <code>--force-with-lease</code>, không dùng <code>--force</code> trần.','After rebasing your own branch push with <code>--force-with-lease</code>, never bare <code>--force</code>.'),t('Muốn <code>git pull</code> luôn rebase thay vì merge: đặt <code>git config --global pull.rebase true</code> (nhớ thống nhất với nhóm, như ở bài 4).','To make <code>git pull</code> rebase instead of merge: <code>git config --global pull.rebase true</code> (agree with your team, as in part 4).')])
    o+=h2('trong-odoo',t('Rebase trong quy trình Odoo của nhóm','Rebase in a team\'s Odoo workflow'))
    o+=tbl([t('Thời điểm','Moment'),t('Làm gì','Do')],[[t('Trước khi mở MR','Before opening the MR'),t('Gộp commit “wip”, “fix typo”; lời nhắn theo <code>[TAG] module: ...</code> của Odoo','Fold “wip” and “fix typo” commits; use Odoo\'s <code>[TAG] module: ...</code> messages')],[t('<code>main</code> đã đi trước khi MR còn mở','<code>main</code> moved on while the MR is open'),t('<code>git rebase main</code> rồi <code>push --force-with-lease</code> để GitLab hết báo lệch','<code>git rebase main</code> then <code>push --force-with-lease</code> so GitLab stops reporting it behind')],[t('Sau khi reviewer đã comment','After reviewers commented'),t('Ưu tiên thêm commit mới thay vì viết lại, để reviewer thấy được phần đã sửa','Prefer adding commits over rewriting, so reviewers can see what changed')],[t('Nhánh phát hành của khách (ví dụ <code>20.0</code>)','A client\'s release branch (for example <code>20.0</code>)'),t('Không rebase; dùng merge hoặc cherry-pick (bài 9)','Do not rebase; use merge or cherry-pick (part 9)')]])
    o+=call(t('Lỗi hay gặp khi mới học','Common beginner mistakes'),[
        t('<strong>Push thường bị từ chối sau rebase.</strong> Đó là điều bình thường vì mã băm đã đổi (xem phần push ở trên). Dùng <code>--force-with-lease</code> trên nhánh riêng; nếu nhánh có người khác cùng làm thì dừng lại và trao đổi.','<strong>A plain push is rejected after a rebase.</strong> That is normal because the hashes changed (see the push above). Use <code>--force-with-lease</code> on your own branch; if someone else shares the branch, stop and talk first.'),
        t('<strong>Rebase lên nhánh chung rồi ép push.</strong> Đồng nghiệp kéo về sẽ thấy các commit trùng lặp hoặc xung đột lạ. Nếu lỡ làm, báo ngay cho nhóm và dùng <code>reflog</code> (bài 7) để khôi phục trạng thái cũ.','<strong>Rebasing a shared branch and force-pushing.</strong> Colleagues who pull will see duplicated commits or odd conflicts. If you did it, tell the team right away and use the <code>reflog</code> (part 7) to restore the old state.'),
        t('<strong>Nhầm “ours” và “theirs”.</strong> Khi rebase, <code>git restore --theirs</code> lấy phiên bản <em>của bạn</em>, ngược với merge. Hãy đọc file kết quả thay vì tin vào tên cờ.','<strong>Mixing up “ours” and “theirs”.</strong> During a rebase, <code>git restore --theirs</code> takes <em>your</em> version, the opposite of a merge. Read the resulting file instead of trusting the flag name.'),
        t('<strong>Quên mình đang giữa một rebase.</strong> <code>git status</code> sẽ ghi <em>rebase in progress</em>; hoàn tất bằng <code>--continue</code> hoặc thoát bằng <code>--abort</code> chứ đừng commit lung tung.','<strong>Forgetting you are in the middle of a rebase.</strong> <code>git status</code> says <em>rebase in progress</em>; finish with <code>--continue</code> or bail out with <code>--abort</code> rather than committing at random.')])
    o+=h2('tong-ket',t('Tổng kết','Summary'))
    o+=ul([t('Rebase phát lại commit của nhánh lên đỉnh mới, cho lịch sử thẳng; commit sau rebase có mã băm mới.','Rebase replays a branch\'s commits on a new tip for a straight history; commits get new hashes.'),t('<code>rebase -i</code> với <code>fixup</code>/<code>squash</code>/<code>reword</code>/<code>drop</code> làm gọn nhánh; <code>--autosquash</code> lo các commit <code>--fixup</code>.','<code>rebase -i</code> with <code>fixup</code>/<code>squash</code>/<code>reword</code>/<code>drop</code> tidies a branch; <code>--autosquash</code> handles <code>--fixup</code> commits.'),t('Xung đột khi rebase: sửa, <code>git add</code>, <code>git rebase --continue</code>; “ours” và “theirs” bị đảo.','Conflicts during a rebase: fix, <code>git add</code>, <code>git rebase --continue</code>; “ours” and “theirs” are swapped.'),t('Chỉ rebase nhánh riêng; push lại bằng <code>--force-with-lease</code>.','Only rebase your own branch; push again with <code>--force-with-lease</code>.')])
    o+=p(t('Bài tiếp theo giải quyết những tình huống “giữa chừng” của đời thực: đang dở tay thì có hotfix gấp (<code>stash</code>), cần mang đúng một commit sang nhánh khác (<code>cherry-pick</code>) và đánh dấu bản phát hành (<code>tag</code>).','The next part tackles real-life “mid-task” situations: an urgent hotfix lands while you are halfway through something (<code>stash</code>), you need to carry exactly one commit to another branch (<code>cherry-pick</code>) and you want to mark a release (<code>tag</code>).'))
    o+=cta(vi,CTA)
    o+='\n'+I+'<h2 id="faq">'+t('Câu hỏi thường gặp','Frequently asked questions')+'</h2>\n'+I+'{FAQ}\n'
    o+='\n'+I+'<h2 id="nguon">'+t('Nguồn tham khảo','References')+'</h2>\n'+SRC
    return o
write('.',build(True),build(False))
